def get_osrm_live_route(coords: List[Tuple[float, float]]) -> Optional[List[List[float]]]:
    """Query public OSRM router for arbitrary coordinate sequences with timeout & error handling."""
    if len(coords) < 2:
        return [[c[0], c[1]] for c in coords]
    try:
        coord_str = ';'.join(f'{lng:.6f},{lat:.6f}' for lat, lng in coords)
        url = f'http://router.project-osrm.org/route/v1/driving/{coord_str}?overview=full&geometries=geojson'
        req = urllib.request.Request(url, headers={'User-Agent': 'UrbanTwin/1.0'})
        with urllib.request.urlopen(req, timeout=4) as resp:
            data = json.loads(resp.read().decode('utf-8'))
            pts = data['routes'][0]['geometry']['coordinates']
            return [[round(c[1], 6), round(c[0], 6)] for c in pts]
    except Exception:
        return None

def get_road_path_between_cameras(cam1_id: str, cam2_id: str) -> List[List[float]]:
    """Retrieve real road polyline connecting two cameras."""
    key = f'{cam1_id}_{cam2_id}'
    if key in CAMERA_LINK_PATHS:
        return CAMERA_LINK_PATHS[key]
    
    # Try reverse
    rev_key = f'{cam2_id}_{cam1_id}'
    if rev_key in CAMERA_LINK_PATHS:
        return [list(pt) for pt in reversed(CAMERA_LINK_PATHS[rev_key])]
        
    return []

def get_corridor_road_path(corridor_id: str, fallback_juncs: List[dict] = None) -> List[List[float]]:
    """Retrieve road-aligned coordinates for a green corridor."""
    # Check aliases
    clean_id = corridor_id.upper()
    if clean_id in ["CORR-CARDIAC-911", "CORRIDOR-ALS-911"]:
        return CORRIDOR_ROAD_PATHS.get('CORRIDOR-ALS-911', [])
    elif clean_id in ["CORR-FIRE-4ALARM", "CORRIDOR-FIRE-101"]:
        return CORRIDOR_ROAD_PATHS.get('CORRIDOR-FIRE-101', [])
    elif clean_id in ["CORR-ORGAN-EXP", "CORRIDOR-ORGAN-5500"]:
        return CORRIDOR_ROAD_PATHS.get('CORRIDOR-ORGAN-5500', [])
        
    if corridor_id in CORRIDOR_ROAD_PATHS:
        return CORRIDOR_ROAD_PATHS[corridor_id]
        
    # Attempt dynamic OSRM if fallback junctions provided
    if fallback_juncs and len(fallback_juncs) >= 2:
        pts = [(j["lat"], j["lng"]) for j in fallback_juncs]
        live = get_osrm_live_route(pts)
        if live:
            return live
            
    return []

def map_gis_to_3d_coordinates(gis_coords: List[List[float]]) -> List[List[float]]:
    """
    Convert GIS [lat, lng] path to 3D WebGL coordinates centered on Kolkata twin origin.
    Origin reference: Park Circus (lat=22.5438, lng=88.3683) -> (0, 1.2, 0).
    Scale factors tuned for realistic city layout in home-3d and whatif-3d.
    """
    ref_lat = 22.5438
    ref_lng = 88.3683
    # 1 deg lat approx 111 km, 1 deg lng approx 102 km
    coords_3d = []
    for pt in gis_coords:
        lat, lng = pt[0], pt[1]
        x = round((lng - ref_lng) * 450.0, 2)
        z = round((ref_lat - lat) * 480.0, 2)
        coords_3d.append([x, 1.2, z])
    return coords_3d

def get_trajectory_road_path(waypoints_raw: List[dict]) -> List[List[float]]:
    """
    Stitch continuous turn-by-turn road polyline across consecutive camera sightings.
    """
    if not waypoints_raw:
        return []
    if len(waypoints_raw) == 1:
        return [[waypoints_raw[0]["lat"], waypoints_raw[0]["lng"]]]
        
    stitched_path: List[List[float]] = []
    for i in range(len(waypoints_raw) - 1):
        c1 = waypoints_raw[i]["camera_id"]
        c2 = waypoints_raw[i + 1]["camera_id"]
        link = get_road_path_between_cameras(c1, c2)
        
        if not link:
            # Fallback to OSRM query
            p1 = (waypoints_raw[i]["lat"], waypoints_raw[i]["lng"])
            p2 = (waypoints_raw[i + 1]["lat"], waypoints_raw[i + 1]["lng"])
            live = get_osrm_live_route([p1, p2])
            link = live if live else [[p1[0], p1[1]], [p2[0], p2[1]]]
            
        if stitched_path:
            # Avoid duplicate vertex at joint
            stitched_path.extend(link[1:])
        else:
            stitched_path.extend(link)
            
    return stitched_path
